/*
 * Doorprints service worker (S4-05).
 *
 * Hand-written rather than generated by @angular/pwa: adding @angular/service-worker would mean a new npm
 * dependency and a regenerated lock file, and the caching this app needs is small and worth being explicit about.
 *
 * **Stamped per build.** This file in `public/` is a template: `npm run build` runs `scripts/sw-precache.mjs` as
 * its `postbuild` step, which writes this build's id into BUILD and the list of every file in the build output
 * into PRECACHE (in dist/web/browser/sw.js only). That is what makes the rest work:
 *  - every build's sw.js has different bytes, so the browser sees an update, `updatefound` fires, and the
 *    "new version, reload" banner appears;
 *  - every build gets its own cache (the id is in its name), and `activate` deletes the previous build's, so
 *    Cache Storage holds one build, not every build ever deployed, next to the user's photos in IndexedDB;
 *  - `install` downloads the whole build — entry bundles, every lazy route chunk, the MapLibre worker, icons,
 *    manifest — before the worker takes control, so the first offline start after a single online visit works,
 *    even though the page itself loaded those files before this worker was registered;
 *  - unhashed files (the MapLibre worker, the manifest, icons) are served from *this build's* copy, so a new main
 *    bundle is never paired with an old cached MapLibre worker.
 * Served unstamped (`ng serve` serves `public/` as is), BUILD keeps its placeholder and the worker caches nothing
 * and answers nothing, so development always sees the network.
 *
 * Rules, from docs/11 section 5.10 "Caching":
 *  - the app shell and this build's files are cached, so the app starts with no network;
 *  - **API responses are never cached** — the user's data lives in IndexedDB under the app's control, and a stale
 *    copy of api/... in Cache Storage would be both confusing and a privacy leak on a shared computer;
 *  - map tiles are never cached (OpenFreeMap fair use), and no cross-origin request is touched at all;
 *  - navigations are answered with this build's shell from the cache first, so a weak connection never means a
 *    blank page;
 *  - a new build takes effect after the user agrees, not in the middle of typing: the page is told and reloads.
 *
 * **Nothing here is hardcoded to the site root.** The live site is served from `/` (the root of its own origin,
 * https://doorprints.web.app on Firebase Hosting), but the same bytes work under a sub-path such as `/doorprints/`
 * when built with that base href. `self.registration.scope` is the scope the page asked for, which `PwaService`
 * derives from `<base href>`, so BASE below is the directory this build was deployed into on whichever host is
 * serving it, and PRECACHE is relative to it.
 */

/** This build's id (16 hex characters once stamped). The literal is replaced by scripts/sw-precache.mjs. */
const BUILD = '__BUILD_ID__';
/** Every file of this build, relative to BASE: `index.html`, `main-….js`, `chunk-….js`, `maplibre/…`, `icons/…`. */
const PRECACHE = [/*__PRECACHE__*/];
/** False when served straight from `public/` (the dev server): then nothing is cached and nothing intercepted. */
const STAMPED = /^[0-9a-f]{16}$/.test(BUILD);

/** Absolute URL of the deployed app directory, ending in `/` — `/` on Firebase Hosting, or a sub-path. */
const BASE = new URL('./', self.registration.scope);

/**
 * Prefix of every cache this app owns. **Paired with `CACHE_NAME_PREFIX` in `src/app/data/local-store.service.ts`**
 * ("remove all my data from this browser"), which filters by the same prefix; the two strings must stay equal, and
 * a service worker in `public/` cannot import from the bundle, so they are written out in both places.
 */
const CACHE_PREFIX = 'doorprints-shell-';

/**
 * This build's cache: `doorprints-shell-<build id><base path>`. The build id makes each deploy a new cache that
 * `activate` can drop the old one for; the **deployment path** is part of the name because Cache Storage is
 * scoped to the *origin*, not to the app: on a shared host (a GitHub Pages project site,
 * `https://<owner>.github.io/<repo>/`) the origin is shared with every other project site of that owner, and a `/`
 * deployment and a sub-path deployment must not delete each other's cache. On Firebase Hosting the origin is the
 * app's own, and the path is simply `/`.
 */
const CACHE = `${CACHE_PREFIX}${BUILD}${BASE.pathname}`;

/**
 * True for a cache this worker may delete: one of **our** caches, from **this** deployment path, that is not this
 * build's. `caches.keys()` lists every cache on the origin, so a blanket "delete everything that is not CACHE"
 * would wipe a sibling app's offline copy on a shared host — the same "another app on this host is none of our
 * business" rule the fetch handler applies with `url.pathname.startsWith(BASE.pathname)`. The segment between the
 * prefix and the path is the build id (it was the fixed `v1` before builds were stamped); either way it has no
 * `/`, so the first `/` after the prefix starts the deployment path.
 */
function isStaleOwnCache(name) {
  if (name === CACHE || !name.startsWith(CACHE_PREFIX)) return false;
  const slash = name.indexOf('/', CACHE_PREFIX.length);
  // Before the name carried the deployment path there was exactly one, unscoped, cache; no worker uses it now.
  if (slash === -1) return true;
  return name.slice(slash) === BASE.pathname;
}

/** The app shell, as a path so it can be compared with a request's pathname. */
const SHELL = new URL('index.html', BASE).pathname;
/** Absolute pathnames of everything precached, for the cache-first decision in `fetch`. */
const PRECACHED = new Set(PRECACHE.map((path) => new URL(path, BASE).pathname));
/**
 * Hashed build outputs: `main-XXXXXXXX.js`, `chunk-XXXXXXXX.js`, `polyfills-…`, `styles-….css` (esbuild names are
 * upper-case base32; Angular's chunk optimizer can emit Rollup's `[a-zA-Z0-9_-]` hashes), and `media/`. A given
 * name always has the same bytes, so these are safe cache-first even when a stale tab asks for a previous build's.
 */
const HASHED = /-[A-Za-z0-9_-]{8}\.(?:js|css)$/;
const MEDIA = new URL('media/', BASE).pathname;
/**
 * Prefixes of an API served from this same origin; never cached. Both forms are bypassed: `HouseApiService` asks
 * for root-absolute `/api/...` when no server has been configured (the dev proxy's shape), and a reverse proxy in
 * front of a self-hosted deployment may instead put the API under the app's own directory.
 */
const API_PREFIXES = ['/api/', new URL('api/', BASE).pathname];
/** This file, so a request for it is always answered by the network. */
const SELF_PATH = new URL('sw.js', BASE).pathname;

/**
 * A response that can be stored and later served for any request. A response that followed a redirect is
 * refused by the browser when replayed for a navigation (its redirect mode is "manual"), so it is re-wrapped.
 */
async function storable(response) {
  if (!response.redirected) return response;
  return new Response(await response.blob(), {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

/**
 * Downloads the whole build into CACHE, bypassing the HTTP cache (`cache: 'reload'`) so a copy the browser kept
 * from a previous deploy cannot sneak in (hashed names excepted, see below). **Any failure fails the install**:
 * a worker that took control with half a build would start offline to a blank page, which is worse than no
 * worker; the browser simply tries again on the next visit.
 *
 * The shell is fetched as the directory (BASE) rather than as `index.html`, because some hosts answer
 * `/index.html` with a redirect to `/` (Cloudflare Pages does, for one), and the directory works on every host;
 * it is stored under SHELL whatever URL served it. The shell must be HTML and nothing else may be: a captive portal's
 * sign-in page stored as `main-….js` would be the same blank page. (Only HTML is refused, not "anything but
 * JavaScript", so a host's odd type for `.mjs` cannot turn into "no offline start at all".)
 */
async function precache() {
  const cache = await caches.open(CACHE);
  await Promise.all(
    PRECACHE.map(async (path) => {
      const isShell = path === 'index.html';
      const url = isShell ? BASE.href : new URL(path, BASE).href;
      // A content-hashed name always has the same bytes, so the copy the page has just loaded is the right one and
      // need not be downloaded twice (this app is used on metered connections); every other file bypasses the HTTP
      // cache. (The host sends no long-lived caching rule for these files, see web/README.md "Deploy": "hashed"
      // is a property of the name, not a promise from the server.)
      const contentHashed = HASHED.test(path) || path.startsWith('media/');
      const get = (mode) => fetch(new Request(url, { cache: mode, credentials: 'same-origin' }));
      let response = await get(contentHashed ? 'default' : 'reload');
      // ...unless the HTTP cache holds the wrong bytes under that name. A host's SPA fallback answers a file that
      // no longer exists with the HTML shell and status 200 (the `**` rewrite in web/firebase.json does), so a tab
      // left open over a deploy can have stored HTML as `chunk-….js`; after a rollback brings that hash back, the
      // cached copy would fail every install for as long as it lives. One fresh download settles it either way.
      if (contentHashed && !isAcceptable(path, isShell, response)) response = await get('reload');
      if (!response.ok) throw new Error(`precache ${path}: HTTP ${response.status}`);
      if (!isAcceptable(path, isShell, response)) {
        throw new Error(`precache ${path}: unexpected ${response.headers.get('content-type') || 'no content type'}`);
      }
      await cache.put(isShell ? SHELL : url, await storable(response));
    }),
  );
}

/**
 * True when `response` may be stored as `path`: a success, and HTML only for the shell and `.html` files. The
 * shell must be HTML; nothing else may be, because an HTML page under a script's name is a host's SPA fallback or
 * a captive portal, never the file.
 *
 * **Paired with `isAcceptable` in `scripts/sw-precache-core.mjs`**, which `src/app/core/sw-precache.spec.ts`
 * tests; a worker in `public/` cannot import it, so the two bodies must stay the same.
 */
function isAcceptable(path, isShell, response) {
  if (!response.ok) return false;
  const html = (response.headers.get('content-type') || '').includes('text/html');
  return isShell ? html : !html || path.endsWith('.html');
}

self.addEventListener('install', (event) => {
  if (!STAMPED) return;
  event.waitUntil(
    precache().catch(async (err) => {
      // Do not leave half a build behind under this build's name; then reject, which fails the install.
      await caches.delete(CACHE).catch(() => undefined);
      throw err;
    }),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter(isStaleOwnCache).map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

// The page asks for the new version to take over once the user has agreed to reload.
self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  if (!STAMPED) return;
  const request = event.request;
  if (request.method !== 'GET') return;

  let url;
  try {
    url = new URL(request.url);
  } catch {
    return;
  }
  // Only this origin: tiles, fonts and the user's own API server are left to the browser.
  if (url.origin !== self.location.origin) return;
  // Only this deployment: another app on the same host (a second project Pages site) is none of our business.
  if (!url.pathname.startsWith(BASE.pathname)) return;
  if (API_PREFIXES.some((p) => url.pathname === p.slice(0, -1) || url.pathname.startsWith(p))) return;
  if (url.pathname === SELF_PATH) return;

  // Navigations: **this build's shell, from the cache, first** — for every route of the app.
  //
  // Network-first had no timeout, so on the connection this app is used on — a basement flat, a site visit, a
  // 4G signal that neither works nor fails — a local-first app showed a blank page for tens of seconds while the
  // precached index.html of this very build sat in CACHE. The cache is per build, so cache-first cannot serve a
  // stale shell with missing chunks: a new deploy arrives as a new worker, `updatefound` shows the "new version,
  // Reload" banner, and the user reloads when it suits them (docs/05 §14.4). Network-first also defeated that
  // banner: an online user silently got the new index.html under the old worker and was then told to reload.
  //
  // The shell is never written from a navigation response (the one in CACHE is the one `install` stored with this
  // build's bundles). A navigation to one of this build's own files (`manifest.webmanifest` typed into the address
  // bar) gets that file, and to any other path with a file extension goes to the network untouched, so the
  // app never replaces a picture or a JSON file on screen. See navigationPlan below.
  if (request.mode === 'navigate') {
    const plan = navigationPlan(url.pathname);
    if (plan === 'network') return;
    const key = plan === 'shell' ? SHELL : request;
    event.respondWith(
      caches
        .match(key, { cacheName: CACHE })
        .then((cached) => cached ?? fetch(request))
        .catch(() => Response.error()),
    );
    return;
  }

  // This build's files and anything with a content hash in its name: cache first. `caches.match` without a
  // cacheName searches every cache on the origin; name ours.
  if (PRECACHED.has(url.pathname) || HASHED.test(url.pathname) || url.pathname.startsWith(MEDIA)) {
    event.respondWith(
      caches.match(request, { cacheName: CACHE }).then((cached) => cached ?? fetchAndKeep(request)),
    );
    return;
  }

  // Anything else in this deployment has an unhashed name that is not part of this build (a file added by hand on
  // the host, say): the network first, so it can never go stale, and the last copy only when offline.
  event.respondWith(
    fetchAndKeep(request).catch(async () => (await caches.match(request, { cacheName: CACHE })) ?? Response.error()),
  );
});

/**
 * How a navigation inside this deployment is answered: `'shell'` (this build's index.html from CACHE), `'file'`
 * (this build's copy of a precached file) or `'network'` (left to the browser).
 *
 * **Paired with `navigationPlan` in `scripts/sw-precache-core.mjs`**, which `src/app/core/sw-precache.spec.ts`
 * tests; a worker in `public/` cannot import it, so the two bodies must stay the same.
 */
function navigationPlan(pathname) {
  if (pathname === SHELL || pathname === BASE.pathname) return 'shell';
  if (PRECACHED.has(pathname)) return 'file';
  const last = pathname.slice(pathname.lastIndexOf('/') + 1);
  return last.includes('.') ? 'network' : 'shell';
}

/**
 * Fetches `request` and keeps a successful same-origin answer in this build's cache. An HTML answer for a path
 * that is not `.html` is passed through but never kept: it is the host's SPA fallback for a file that does not
 * exist (a previous build's chunk asked for by a stale tab), and keeping it would serve the shell under that
 * name for the rest of this build's life.
 */
function fetchAndKeep(request) {
  return fetch(request).then((response) => {
    const path = new URL(request.url).pathname;
    const html = response && (response.headers.get('content-type') || '').includes('text/html');
    if (html && !path.endsWith('.html')) return response;
    if (response && response.ok && response.type === 'basic' && !response.redirected) {
      const copy = response.clone();
      caches
        .open(CACHE)
        .then((cache) => cache.put(request, copy))
        .catch(() => undefined);
    }
    return response;
  });
}
